-- 録画ファイルの場所を、置き場からの相対に書き換える (schema.ts の mediaPath)。
-- 生TS はファイル名だけ、焼いたものは `シリーズ/ファイル` (Season フォルダの古い形は `シリーズ/Season 年/ファイル`)。
-- 絶対パス (`/` で始まるもの) だけを書き換える。Windows で書かれた行は絶対のまま残り、mediaPath がそのまま返す
UPDATE `recordings` SET `ts_path` = substr(`ts_path`, length(rtrim(`ts_path`, replace(`ts_path`, '/', ''))) + 1) WHERE `ts_path` LIKE '/%';--> statement-breakpoint
UPDATE `recordings` SET `library_path` = CASE WHEN substr(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), length(rtrim(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), replace(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), '/', ''))) + 1) LIKE 'Season %' THEN substr(`library_path`, length(rtrim(substr(rtrim(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), replace(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), '/', '')), 1, length(rtrim(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), replace(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), '/', ''))) - 1), replace(substr(rtrim(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), replace(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), '/', '')), 1, length(rtrim(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), replace(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), '/', ''))) - 1), '/', ''))) + 1) ELSE substr(`library_path`, length(rtrim(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), replace(substr(rtrim(`library_path`, replace(`library_path`, '/', '')), 1, length(rtrim(`library_path`, replace(`library_path`, '/', ''))) - 1), '/', ''))) + 1) END WHERE `library_path` LIKE '/%';--> statement-breakpoint
UPDATE `recordings` SET `alt_path` = CASE WHEN substr(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), length(rtrim(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), replace(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), '/', ''))) + 1) LIKE 'Season %' THEN substr(`alt_path`, length(rtrim(substr(rtrim(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), replace(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), '/', '')), 1, length(rtrim(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), replace(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), '/', ''))) - 1), replace(substr(rtrim(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), replace(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), '/', '')), 1, length(rtrim(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), replace(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), '/', ''))) - 1), '/', ''))) + 1) ELSE substr(`alt_path`, length(rtrim(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), replace(substr(rtrim(`alt_path`, replace(`alt_path`, '/', '')), 1, length(rtrim(`alt_path`, replace(`alt_path`, '/', ''))) - 1), '/', ''))) + 1) END WHERE `alt_path` LIKE '/%';
